"use client";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import { AlertTriangle, AlertCircle, AlertOctagon } from "lucide-react";

/* ================= TYPES ================= */

export interface Anomaly {
  id: string;
  identityId: string;
  cameraId: string;
  anomalyType: string;
  timestamp: string;
}

interface AnomalyListProps {
  anomalies: Anomaly[];
  isLoading?: boolean;
}

/* ================= HELPERS ================= */

const formatDate = (dateString: string) => {
  return new Date(dateString).toLocaleString();
};

/* derive severity from anomaly type */

const getSeverity = (type: string) => {
  const t = type?.toLowerCase() || "";

  if (t.includes("loiter")) return "high";
  if (t.includes("unusual")) return "medium";

  return "low";
};

const getSeverityBadge = (severity: string) => {
  switch (severity) {
    case "high":
      return "bg-red-500/20 text-red-400 border-red-500/50";
    case "medium":
      return "bg-yellow-500/20 text-yellow-400 border-yellow-500/50";
    case "low":
      return "bg-blue-500/20 text-blue-400 border-blue-500/50";
    default:
      return "bg-gray-500/20 text-gray-400 border-gray-500/50";
  }
};

const getSeverityIcon = (severity: string) => {
  switch (severity) {
    case "high":
      return <AlertOctagon size={20} />;
    case "medium":
      return <AlertTriangle size={20} />;
    case "low":
      return <AlertCircle size={20} />;
    default:
      return <AlertCircle size={20} />;
  }
};

/* ================= COMPONENT ================= */

export function AnomalyList({
  anomalies,
  isLoading = false,
}: AnomalyListProps) {
  if (isLoading) {
    return (
      <div className="space-y-4">
        {[...Array(5)].map((_, i) => (
          <Skeleton key={i} className="h-24 bg-[#333]" />
        ))}
      </div>
    );
  }

  if (anomalies.length === 0) {
    return (
      <Card className="bg-[#222] border-[#333] p-12 text-center">
        <div className="space-y-2">
          <p className="text-lg text-gray-300">All Clear</p>
          <p className="text-gray-400">No anomalies detected</p>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {anomalies.map((anomaly) => {
        const severity = getSeverity(anomaly.anomalyType);

        return (
          <Card
            key={anomaly.id}
            className={`bg-[#222] border ${
              getSeverityBadge(severity).split(" ").slice(-1)[0]
            } hover:border-opacity-100 transition-colors p-4`}
          >
            <div className="flex items-start gap-4">
              {/* Icon */}

              <div
                className={`flex-shrink-0 ${
                  getSeverityBadge(severity).split(" ")[1]
                }`}
              >
                {getSeverityIcon(severity)}
              </div>

              {/* Content */}

              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between gap-4 mb-2">
                  <div>
                    <h4 className="text-sm font-semibold text-white capitalize">
                      {anomaly.anomalyType}
                    </h4>

                    <p className="text-xs text-gray-400 mt-1">
                      {formatDate(anomaly.timestamp)}
                    </p>
                  </div>

                  <Badge
                    className={`${getSeverityBadge(severity)} border flex-shrink-0 capitalize`}
                  >
                    {severity}
                  </Badge>
                </div>

                <div className="grid grid-cols-2 gap-4 mt-3 pt-3 border-t border-[#333]">
                  <div>
                    <p className="text-xs text-gray-500">Identity ID</p>

                    <p className="text-sm font-mono text-cyan-400">
                      {anomaly.identityId}
                    </p>
                  </div>

                  <div>
                    <p className="text-xs text-gray-500">Camera ID</p>

                    <p className="text-sm text-gray-300">{anomaly.cameraId}</p>
                  </div>
                </div>
              </div>
            </div>
          </Card>
        );
      })}
    </div>
  );
}
